extern "C" void raster(const double *samples,int n,int res,double*out){
 std::fill(out,out+res*res,0.);double px=1024./res;
 for(int k=0;k<n;k++){
  double x=samples[k*4],y=samples[k*4+1],w=samples[k*4+2],th=samples[k*4+3];
  double d=(1.38+1.075*(w*.22185986964255727+.3)/1.187)/.22185986964255727;
  double ex=cos(th),ey=sin(th),nx=-ey,ny=ex;
  double xx[4]={x+w/2*nx,x-w/2*nx,x-d*ex+w/2*nx,x-d*ex-w/2*nx};
  double yy[4]={y+w/2*ny,y-w/2*ny,y-d*ey+w/2*ny,y-d*ey-w/2*ny};
  int x0=std::max(0,int(floor((*std::min_element(xx,xx+4)+.5)/px))-1),x1=std::min(res-1,int(ceil((*std::max_element(xx,xx+4)+.5)/px))+1);
  int y0=std::max(0,int(floor((*std::min_element(yy,yy+4)+.5)/px))-1),y1=std::min(res-1,int(ceil((*std::max_element(yy,yy+4)+.5)/px))+1);
  for(int i=y0;i<=y1;i++)for(int j=x0;j<=x1;j++){
   double qx=(j+.5)*px-.5-x,qy=(i+.5)*px-.5-y;
   double s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
   double f=d*(1.-4.*t*t/(w*w))-s,g=8.*d*t/(w*w);
   double sd=std::min(s,f/sqrt(1.+g*g));
   double a=std::max(0.,std::min(1.,sd/px+.5));
   out[i*res+j]=std::max(out[i*res+j],a);
  }
